// Package cli holds the hand-written transaction commands of x/entityregistry;
// the rest are generated by autocli.
package cli

import (
	"encoding/hex"

	"github.com/cosmos/cosmos-sdk/client"
	"github.com/cosmos/cosmos-sdk/client/flags"
	"github.com/cosmos/cosmos-sdk/client/tx"
	sdk "github.com/cosmos/cosmos-sdk/types"
	"github.com/spf13/cobra"

	"github.com/saicon-network/saicon/chain/crypto/vrf"
	"github.com/saicon-network/saicon/chain/x/entityregistry/types"
)

// FlagVrfKeyFile names the VRF key file flag.
const FlagVrfKeyFile = "vrf-key-file"

// NewOfferVrfKeyCmd offers the key in --vrf-key-file for the --from account's
// validator, with a proof of possession made locally.
func NewOfferVrfKeyCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "offer-vrf-key --vrf-key-file <file> --from <operator>",
		Short: "Offer a VRF key for your validator, with a proof of possession made locally",
		Long: "Offer the VRF key in --vrf-key-file for the validator of the --from account. The proof of " +
			"possession is computed locally over the client's chain id, the validator address and the key. " +
			"An attestor then binds the offered key with 'tx entityregistry attest … --vrf-keys'.",
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			clientCtx, err := client.GetClientTxContext(cmd)
			if err != nil {
				return err
			}
			path, err := cmd.Flags().GetString(FlagVrfKeyFile)
			if err != nil {
				return err
			}
			key, err := vrf.LoadKeyFile(path)
			if err != nil {
				return err
			}
			val := sdk.ValAddress(clientCtx.GetFromAddress())
			pop := key.Prove(types.PopAlpha(clientCtx.ChainID, val, key.PublicKey()))
			msg := &types.MsgOfferVrfKey{
				Operator:          clientCtx.GetFromAddress().String(),
				VrfPublicKey:      hex.EncodeToString(key.PublicKey()),
				ProofOfPossession: hex.EncodeToString(pop),
			}
			return tx.GenerateOrBroadcastTxCLI(clientCtx, cmd.Flags(), msg)
		},
	}
	flags.AddTxFlagsToCmd(cmd)
	cmd.Flags().String(FlagVrfKeyFile, "", "path to the VRF key file written by 'saicond vrf keygen'")
	_ = cmd.MarkFlagRequired(FlagVrfKeyFile)
	return cmd
}
